PrologProcedure:
#Region Seed tax bands — employer payroll tax + employee income tax, by jurisdiction
cCube = 'WFP Tax Bands';

# jurisdiction;taxtype;band;from;to;rate
vB =
'UK;Employer Payroll Tax;Band 1;0;9100;0~' |
'UK;Employer Payroll Tax;Band 2;9100;99999999;0.138~' |
'US-NY;Employer Payroll Tax;Band 1;0;168600;0.09~' |
'US-NY;Employer Payroll Tax;Band 2;168600;99999999;0.0145~' |
'NZ;Employer Payroll Tax;Band 1;0;142283;0.016~' |
'NZ;Employer Payroll Tax;Band 2;142283;99999999;0~' |
'UK;Employee Income Tax;Band 1;0;12570;0~' |
'UK;Employee Income Tax;Band 2;12570;50270;0.20~' |
'UK;Employee Income Tax;Band 3;50270;125140;0.40~' |
'UK;Employee Income Tax;Band 4;125140;99999999;0.45~' |
'US-NY;Employee Income Tax;Band 1;0;11600;0.10~' |
'US-NY;Employee Income Tax;Band 2;11600;47150;0.18~' |
'US-NY;Employee Income Tax;Band 3;47150;100525;0.26~' |
'US-NY;Employee Income Tax;Band 4;100525;191950;0.30~' |
'US-NY;Employee Income Tax;Band 5;191950;99999999;0.35~' |
'NZ;Employee Income Tax;Band 1;0;15600;0.105~' |
'NZ;Employee Income Tax;Band 2;15600;53500;0.175~' |
'NZ;Employee Income Tax;Band 3;53500;78100;0.30~' |
'NZ;Employee Income Tax;Band 4;78100;180000;0.33~' |
'NZ;Employee Income Tax;Band 5;180000;99999999;0.39~';

WHILE( SCAN( '~', vB ) > 1 );
   nS = SCAN( '~', vB );
   vRec = SUBST( vB, 1, nS - 1 ) | ';';
   vB = SUBST( vB, nS + 1, LONG( vB ) - nS );

   nS = SCAN(';',vRec); vJur  = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); vType = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); vBand = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nFrom = NUMBR(SUBST(vRec,1,nS-1)); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nTo   = NUMBR(SUBST(vRec,1,nS-1)); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nRate = NUMBR(SUBST(vRec,1,nS-1));

   CellPutN( nFrom, cCube, vJur, vType, vBand, 'Threshold From' );
   CellPutN( nTo,   cCube, vJur, vType, vBand, 'Threshold To' );
   CellPutN( nRate, cCube, vJur, vType, vBand, 'Rate' );
END;
